    def maxScoreIndices(self, nums: List[int]) -> List[int]:
        n = len(nums)
        left_zeros = [0] * (n + 1)
        right_ones = [0] * (n + 1)

        # Calculate prefix sums for zeros and ones
        for i in range(n):
            left_zeros[i + 1] = left_zeros[i] + (1 if nums[i] == 0 else 0)
            right_ones[n - i - 1] = right_ones[n - i] + (1 if nums[n - i - 1] == 1 else 0)

        max_score = 0
        result = []

        for i in range(n + 1):
            score = left_zeros[i] + right_ones[i]
            if score > max_score:
                max_score = score
                result = [i]
            elif score == max_score:
                result.append(i)

        return result

