class Solution:
    def canIWin(self, maxChoosableInteger: int, desiredTotal: int) -> bool:
        if desiredTotal <= maxChoosableInteger:
            return True
        if (maxChoosableInteger * (maxChoosableInteger + 1) // 2) < desiredTotal:
            return False

        memo = {}

        def canWin(choices, target):
            if target <= 0:
                return False
            if tuple(choices) in memo:
                return memo[tuple(choices)]
            for i in range(len(choices)):
                if choices[i] >= target:
                    return True
                if not canWin(choices[:i] + choices[i+1:], target - choices[i]):
                    memo[tuple(choices)] = True
                    return True
            memo[tuple(choices)] = False
            return False

        return canWin(list(range(1, maxChoosableInteger + 1)), desiredTotal)
