class Solution:
    def maxNumber(self, nums1: List[int], nums2: List[int], k: int) -> List[int]:
        def max_single_array(nums, k):
            drop = len(nums) - k
            stack = []
            for num in nums:
                while drop and stack and stack[-1] < num:
                    stack.pop()
                    drop -= 1
                stack.append(num)
            return stack[:k]

        def merge(arr1, arr2):
            return [max(arr1, arr2).pop(0) for _ in range(k)]

        n, m = len(nums1), len(nums2)
        max_num = [0] * k
        for i in range(max(0, k - m), min(k, n) + 1):
            first = max_single_array(nums1, i)
            second = max_single_array(nums2, k - i)
            num = merge(first, second)
            max_num = max(max_num, num)
        return max_num

