            if visited[x][y]:
                return True
            visited[x][y] = True
            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nx, ny = x + dx, y + dy
                if 0 <= nx < m and 0 <= ny < n and (nx, ny) != (px, py) and grid[nx][ny] == grid[x][y]:
                    if visited[nx][ny] or dfs(nx, ny, x, y):
                        return True
            return False

