class Solution:
    def findClosestElements(self, arr: List[int], k: int, x: int) -> List[int]:
        # Find the insertion point to maintain sorted order
        insert_index = bisect.bisect_left(arr, x)

        # Initialize pointers for left and right
        left = max(0, insert_index - k)
        right = min(len(arr) - 1, insert_index + k - 1)

        # Expand the window to include k closest elements
        while right - left + 1 > k:
            if (x - arr[left]) <= (arr[right] - x):
                right -= 1
            else:
                left += 1

        return arr[left:right+1]

