    def findTheCity(self, n: int, edges: List[List[int]], distanceThreshold: int) -> int:
        # Create a graph from the edges
        graph = defaultdict(list)
        for u, v, w in edges:
            graph[u].append((v, w))
            graph[v].append((u, w))

        def dijkstra(start):
            dist = [float('inf')] * n
