        vowel_to_bit = {'a': 0, 'e': 1, 'i': 2, 'o': 4, 'u': 8}
        seen = {0: -1}
        max_len = 0
        current_xor = 0

        for i, char in enumerate(s):
            if char in vowel_to_bit:
                current_xor ^= 1 << vowel_to_bit[char]
            if current_xor in seen:
                max_len = max(max_len, i - seen[current_xor])
            else:
                seen[current_xor] = i
        return max_len

