    def getMoneyAmount(self, n: int) -> int:
        # Create a 2D DP table to store the minimum cost for the range i to j
        dp = [[0] * (n+1) for _ in range(n+1)]

        # Fill the table using bottom-up approach
        for length in range(2, n+1):  # length of the range
            for i in range(1, n-length+2):
                j = i + length - 1
                dp[i][j] = float('inf')
                for k in range(i, j+1):
                    cost = k + max(dp[i][k-1] if k-1 >= i else 0, dp[k+1][j] if k+1 <= j else 0)
                    dp[i][j] = min(dp[i][j], cost)
        return dp[1][n]

