class Solution:
    def stringHash(self, s: str, k: int) -> str:
        result = ""
        for i in range(0, len(s), k):
            substring = s[i:i+k]
            total_hash = 0
            for char in substring:
                total_hash += ord(char) - ord('a')
            hashed_char = total_hash % 26
            result += chr(ord('a') + hashed_char)
        return result

