class Solution:
    def minimumCost(self, n: int, highways: List[List[int]], discounts: int) -> int:
        # Create adjacency list for the graph
        graph = [[] for _ in range(n)]
        for u, v, w in highways:
            graph[u].append((v, w))
            graph[v].append((u, w))

        # Priority queue to store (cost, node, discounts_used)
        pq = [(0, 0, 0)]  # (cost, node, discounts_used)
        visited = [[float('inf')] * n for _ in range(discounts + 1)]
        visited[0][0] = 0

        while pq:
            cost, node, discounts_used = heapq.heappop(pq)

            if node == n - 1:
                return cost

            for neighbor, weight in graph[node]:
                new_cost = cost + weight
                if new_cost < visited[discounts_used][neighbor]:
                    visited[discounts_used][neighbor] = new_cost
                    heapq.heappush(pq, (new_cost, neighbor, discounts_used))

                if discounts_used < discounts:
                    new_cost_with_discount = cost + weight // 2
                    if new_cost_with_discount < visited[discounts_used + 1][neighbor]:
                        visited[discounts_used + 1][neighbor] = new_cost_with_discount
                        heapq.heappush(pq, (new_cost_with_discount, neighbor, discounts_used + 1))

        return -1
