    def minSwaps(self, s: str) -> int:
        # Count the number of 0s and 1s in the string
        count_0 = s.count('0')
        count_1 = s.count('1')

        # If the difference between the counts of 0s and 1s is more than 1, it's impossible to make the string alternating
