        # Calculate the length of the number where the nth digit is located
        length = 1
        count = 9
        while n > length * count:
            n -= length * count
            length += 1
            count *= 10
        # Find the exact number where the nth digit is located
        start = 10 ** (length - 1)
        start += (n - 1) // length
