class Solution:
    def numSquarefulPerms(self, nums):
        def is_square(n):
            root = isqrt(n)
            return root * root == n

        def backtrack(path, used):
            if len(path) == len(nums):
                return 1
            count = 0
            for i in range(len(nums)):
                if used[i] or (i > 0 and nums[i] == nums[i - 1] and not used[i - 1]):
                    continue
                if not path or is_square(path[-1] + nums[i]):
                    used[i] = True
                    count += backtrack(path + [nums[i]], used)
                    used[i] = False
            return count

        nums.sort()
        return backtrack([], [False] * len(nums))
