from collections import defaultdict, deque

class Solution:
    def minimumTime(self, n: int, relations: List[List[int]], time: List[int]) -> int:
        # Create a graph to represent the dependencies
        graph = defaultdict(list)
        in_degree = [0] * n
        for prev, next in relations:
            graph[prev - 1].append(next - 1)
            in_degree[next - 1] += 1

        # Initialize the time to complete each course
        time_to_complete = time[:]

        # Perform a topological sort using Kahn's algorithm
        queue = deque([i for i in range(n) if in_degree[i] == 0])

        while queue:
            node = queue.popleft()
            for neighbor in graph[node]:
                time_to_complete[neighbor] = max(time_to_complete[neighbor], time_to_complete[node] + time[neighbor])
                in_degree[neighbor] -= 1
                if in_degree[neighbor] == 0:
                    queue.append(neighbor)

        return max(time_to_complete)

