class Solution:
    def reachableNodes(self, edges: List[List[int]], maxMoves: int, n: int) -> int:
        graph = [[] for _ in range(n)]
        for u, v, cnt in edges:
            graph[u].append((v, cnt + 1))
            graph[v].append((u, cnt + 1))

        pq = [(0, 0)]
        dist = [float('inf')] * n
        dist[0] = 0
        while pq:
            d, u = heapq.heappop(pq)
            if d > dist[u]:
