class Solution:
    def findLengthOfShortestSubarray(self, arr: List[int]) -> int:
        n = len(arr)
        left = 0
        right = n - 1

        # Find the longest non-decreasing subarray from the left
        while left + 1 < n and arr[left] <= arr[left + 1]:
            left += 1

        # If the array is already sorted
        if left == n - 1:
            return 0

        # Find the longest non-decreasing subarray from the right
        while right > 0 and arr[right] >= arr[right - 1]:
            right -= 1

        # The result is the minimum of removing elements from the left or right
        result = min(n - left - 1, right)

        # Check the best option between removing from the left or right
        i, j = 0, right
        while i <= left and j < n:
            if arr[i] <= arr[j]:
                result = min(result, j - i - 1)
                i += 1
            else:
                j += 1

        return result

