            if [x, y] == destination:
                return True
            if visited[x][y]:
                return False
            visited[x][y] = True
            for dx, dy in directions:
                nx, ny = x, y
                while is_valid(nx + dx, ny + dy):
                    nx, ny = nx + dx, ny + dy
                if (nx, ny) != (x, y) and dfs(nx, ny):
                    return True
            return False

        return dfs(start[0], start[1])
