class Solution:
    def hasGroupsSizeX(self, deck: List[int]) -> bool:
        if len(deck) < 2:
            return False

        counts = Counter(deck)
        values = list(counts.values())

        def gcd_list(l):
            x = l[0]
            for y in l[1:]:
                x = gcd(x, y)
            return x

        gcd_value = gcd_list(values)

